selector_to_html = {"a[href=\"#enflame-gcu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Enflame GCU<a class=\"headerlink\" href=\"#enflame-gcu\" title=\"Link to this heading\">#</a></h3><p>Provided as a reference example; full production support requires collaboration with the vendor.</p>", "a[href=\"#nvidia-flagos-engine\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">NVIDIA (FlagOS engine)<a class=\"headerlink\" href=\"#nvidia-flagos-engine\" title=\"Link to this heading\">#</a></h3><p>The FlagOS engine registers as an engine vendor (<code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>) on top of the <code class=\"docutils literal notranslate\"><span class=\"pre\">cuda</span></code> device platform, rather than as a standalone platform.</p>", "a[href=\"#platform-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Platform Guide<a class=\"headerlink\" href=\"#platform-guide\" title=\"Link to this heading\">#</a></h1><p>This page summarizes the hardware platforms verl-hardware-plugin ships implementations for. For complete, up-to-date installation and quick-start steps, use the platform guide in the repository (linked for each platform).</p>", "a[href=\"#platform-specific-notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform-Specific Notes<a class=\"headerlink\" href=\"#platform-specific-notes\" title=\"Link to this heading\">#</a></h2><h3>NVIDIA (FlagOS engine)<a class=\"headerlink\" href=\"#nvidia-flagos-engine\" title=\"Link to this heading\">#</a></h3><p>The FlagOS engine registers as an engine vendor (<code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>) on top of the <code class=\"docutils literal notranslate\"><span class=\"pre\">cuda</span></code> device platform, rather than as a standalone platform.</p>", "a[href=\"#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p>Requires <code class=\"docutils literal notranslate\"><span class=\"pre\">/dev/dri</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">/dev/mxcd</span></code> device mounts and <code class=\"docutils literal notranslate\"><span class=\"pre\">mx-smi</span></code> inside the container. Uses MetaX Docker Hub images (for example <code class=\"docutils literal notranslate\"><span class=\"pre\">verl:0.7.1-maca.ai3.5.3.3-torch2.8-py312-ubuntu22.04-amd64</span></code>).</p>", "a[href=\"#cambricon-mlu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Cambricon MLU<a class=\"headerlink\" href=\"#cambricon-mlu\" title=\"Link to this heading\">#</a></h3><p>Use the Cambricon release Docker image in the <code class=\"docutils literal notranslate\"><span class=\"pre\">pytorch_infer</span></code> environment, and install <code class=\"docutils literal notranslate\"><span class=\"pre\">numpy&lt;2</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">TransferQueue</span></code>. Start Ray and run verl examples with the recommended <code class=\"docutils literal notranslate\"><span class=\"pre\">runtime_env.yaml</span></code>:</p>", "a[href=\"#platform-summary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform Summary<a class=\"headerlink\" href=\"#platform-summary\" title=\"Link to this heading\">#</a></h2><p>For CUDA-compatible devices (MetaX, Iluvatar, NVIDIA), <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda.is_available()</span></code> returns True on all of them. The platform layer uses <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor_name</span></code> and SMI-based detection (<code class=\"docutils literal notranslate\"><span class=\"pre\">mx-smi</span></code> for MetaX, <code class=\"docutils literal notranslate\"><span class=\"pre\">nvidia-smi</span></code> for NVIDIA) at first auto-detection to select the correct engine.</p>", "a[href=\"#intel-xpu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Intel XPU<a class=\"headerlink\" href=\"#intel-xpu\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#adding-a-new-platform\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Adding a New Platform<a class=\"headerlink\" href=\"#adding-a-new-platform\" title=\"Link to this heading\">#</a></h2><p>Vendors can add a new hardware platform by:</p>", "a[href=\"#iluvatar-bi-v150\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Iluvatar (BI-V150)<a class=\"headerlink\" href=\"#iluvatar-bi-v150\" title=\"Link to this heading\">#</a></h3><p>Uses the CoreX base image <code class=\"docutils literal notranslate\"><span class=\"pre\">iluvatarcorex-4.4.0-ubuntu24-py312-base</span></code>. Requires verl &gt; 0.8.0 with the plugin registry from <a class=\"reference external\" href=\"https://github.com/verl-project/verl/pull/6086\">verl#6086</a>.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
